vulnerabilities.fix:
Before:
<form method="POST" action="<?=$saveUrl?>" id="FORMACTION">
...
if ($request->getRequestMethod()==='POST' && AccessController::isEditSettings() && $request->get('Update'))
{
    Option::set($module_id, "LOAD_NBRB", ...);

After:
<form method="POST" action="<?=$saveUrl?>" id="FORMACTION">
    <?=bitrix_sessid_post()?>
...
if ($request->getRequestMethod()==='POST' && AccessController::isEditSettings() && $request->get('Update'))
{
    if (!check_bitrix_sessid()) { $APPLICATION->ThrowException('Session expired'); }
    else {
        Option::set($module_id, "LOAD_NBRB", ...);
        // ... остальная запись опций
    }
}

Before:
$httpClient = new HttpClient([
    'socketTimeout'=>10,
    'streamTimeout'=>10,
]);
$httpClient->setHeaders(array(...));
$httpClient->disableSslVerification();

After:
$httpClient = new HttpClient([
    'socketTimeout'=>10,
    'streamTimeout'=>10,
    // проверка сертификата включена по умолчанию; при необходимости — опция модуля
    'disableSslVerification' => \Bitrix\Main\Config\Option::get('awz.currency', 'DISABLE_SSL_VERIFY', 'N') === 'Y',
]);
$httpClient->setHeaders(array(...));
// вызов disableSslVerification() удален

Before:
$httpClient = new HttpClient();
$httpClient->setHeaders(array(...));
$httpClient->disableSslVerification();
$httpClient->setTimeout(static::MAX_TIMEOUT);

After:
$httpClient = new HttpClient();
$httpClient->setHeaders(array(...));
// disableSslVerification() удален — проверка TLS включена по умолчанию
$httpClient->setTimeout(static::MAX_TIMEOUT);

Before:
$httpClient->disableSslVerification();
...
$res = $httpClient->get(static::API_URL.'&date='.$date);

After:
// disableSslVerification() удален — проверка TLS включена по умолчанию
...
$res = $httpClient->get(static::API_URL.'&date='.urlencode((string)$date));
